Write-Host "Decoding Base64 payload..." -ForegroundColor Cyan
$bytes = [System.Convert]::FromBase64String($b64Certificates)

Write-Host "Writing file: $targetFile" -ForegroundColor Cyan
[System.IO.File]::WriteAllBytes($targetFile, $bytes)

if (Test-Path -Path $targetFile) {
    $lineCount = (Get-Content -Path $targetFile).Count
    Write-Host "Done. Wrote $lineCount lines to:" -ForegroundColor Green
    Write-Host "  $targetFile" -ForegroundColor Green
} else {
    Write-Host "FAILED: file was not created." -ForegroundColor Red
    exit 1
}

Write-Host ""
Write-Host "Route available at: /dashboard/certificates" -ForegroundColor Yellow
Write-Host "Reminder: if you have a nav-config or shared sidebar for the web app," -ForegroundColor Yellow
Write-Host "add a Certificates entry there too so it appears on other learner pages." -ForegroundColor Yellow